function [surf_momenttrac,data4plot] = SurfMomentTraction(isurf,nnps,nqpts,ssfac,xlocal,ylocal,zlocal,normalized_moment_increments,nuaxis_surf)%%  called by ComputeForceMatrices%% computes surface forces for bending couples %    surf_momenttrac = zeros(nqpts,3);    zero_trac = zeros(nqpts,1);    norm_mom_incr = zeros(2,1);    nuaxes = zeros(2,1);    momenttrac = zeros(nqpts,1);        data4plot = zeros(3,1); 	            switch isurf            case 1                xcase = zlocal;                ycase = ylocal;                 norm_mom_incr(1)   = normalized_moment_increments(2);                norm_mom_incr(2)   = normalized_moment_increments(3);                nuaxes(1) = nuaxis_surf(3);                nuaxes(2) = nuaxis_surf(2);            case 2                xcase = zlocal;                ycase = ylocal;                 norm_mom_incr(1)   = normalized_moment_increments(2);                norm_mom_incr(2)   = normalized_moment_increments(3);                nuaxes(1) = nuaxis_surf(3);                nuaxes(2) = nuaxis_surf(2);            case 3                xcase = xlocal;                ycase = zlocal;                 norm_mom_incr(1)   = normalized_moment_increments(3);                norm_mom_incr(2)   = normalized_moment_increments(1);                nuaxes(1) = nuaxis_surf(1);                nuaxes(2) = nuaxis_surf(3);            case 4                xcase = xlocal;                ycase = zlocal;                                norm_mom_incr(1)   = normalized_moment_increments(3);                norm_mom_incr(2)   = normalized_moment_increments(1);                nuaxes(1) = nuaxis_surf(1);                nuaxes(2) = nuaxis_surf(3);                            case 5                xcase = ylocal;                ycase = xlocal;                                  norm_mom_incr(1)   = normalized_moment_increments(1);                norm_mom_incr(2)   = normalized_moment_increments(2);                nuaxes(1) = nuaxis_surf(2);                nuaxes(2) = nuaxis_surf(1);                          case 6                xcase = ylocal;                ycase = xlocal;                                 norm_mom_incr(1)   = normalized_moment_increments(1);                norm_mom_incr(2)   = normalized_moment_increments(2);                nuaxes(1) = nuaxis_surf(2);                nuaxes(2) = nuaxis_surf(1);                        end        for j=1:1:nqpts         xidist = 0.0;        etadist = 0.0;              for k = 1:1:nnps                   xidist  =  xidist  + ssfac(k,j)*xcase(k);                   etadist =  etadist + ssfac(k,j)*ycase(k);              end          xidist  = xidist-nuaxes(1);        etadist = etadist-nuaxes(2);         momenttrac(j) = -(norm_mom_incr(1)*xidist + norm_mom_incr(2)*etadist);        switch isurf            case 1                surf_momenttrac= [momenttrac zero_trac zero_trac];            case 2                surf_momenttrac= [momenttrac zero_trac zero_trac];            case 3                surf_momenttrac= [zero_trac momenttrac zero_trac];            case 4                surf_momenttrac= [zero_trac momenttrac zero_trac];                        if(j==1)                            data4plot = [ xidist etadist momenttrac(j)];                        end            case 5                surf_momenttrac= [zero_trac zero_trac momenttrac];            case 6                surf_momenttrac= [zero_trac zero_trac momenttrac];        end        end  